\set ON_ERROR_STOP on

CREATE SCHEMA IF NOT EXISTS public;

CREATE TABLE public.messages (
  id uuid PRIMARY KEY,
  event_id uuid,
  circle_id uuid,
  created_at timestamptz NOT NULL
);

CREATE TABLE public.community_topic_messages (
  id uuid PRIMARY KEY,
  topic_id uuid NOT NULL,
  created_at timestamptz NOT NULL
);

-- Every access path has three same-timestamp rows plus one older row. The
-- compound id cursor must leave the smallest same-timestamp id for page two.
